{
  "per_column": [
    {
      "name": "incident_category",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "Categorising incidents (vpn, network, database, email) gives a real axis to compare resolution times across incident types. Values are well-grounded in short_description text (e.g. 'VPN connection issue' -> vpn, 'Cannot connect to database' -> database). Somewhat overlaps with existing 'category' column but adds finer granularity from free text."
    },
    {
      "name": "problem_symptom_type",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Symptom type (outage vs cannot_connect vs crash) is a strong signal for resolution difficulty and a genuine new grouping axis. Mostly well-read from text, though mapping 'Email system not working properly' to 'outage' is a mild inference; still defensible. Extraction is a sound reading overall."
    },
    {
      "name": "is_unassigned_at_open",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.55,
      "hallucination_observed": false,
      "rationale": "Whether an incident was unassigned at open is a plausible and relevant predictor of longer resolution. However the samples do not show opened-time assignment state, and 'assigned_to' reflects current assignment, not assignment at open time; deriving the 'at_open' temporal claim is only partially supported by the available fields."
    },
    {
      "name": "assignee_resolver_match",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Comparing assigned_to vs closed_by is a reasonable proxy for reassignment/handoff, which correlates with longer resolution. Derivable directly from original columns; NULLs handled sensibly for open/unresolved rows. Genuinely useful new axis."
    },
    {
      "name": "opened_hour_of_day",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.7,
      "hallucination_observed": false,
      "rationale": "Business_hours vs off_hours is a meaningful signal for resolution latency (staffing). Derivable from opened_at. Grounding is only partially checkable here because the samples expose sys_updated_on/closed_at rather than opened_at, but the bucketing concept is sound and warranted."
    },
    {
      "name": "is_recurring_issue_type",
      "analytical_usefulness": 0.35,
      "source_groundedness": 0.4,
      "hallucination_observed": true,
      "rationale": "Value is 'true' for 462/500 rows, making it near-constant and offering little analytical leverage. Grounding is weak: recurrence requires cross-row frequency analysis, yet every sampled row is flagged True with no evident support in its source text, suggesting an unsupported blanket assignment."
    }
  ],
  "analytical_usefulness": 0.72,
  "source_groundedness": 0.72,
  "rationale": "Most added columns provide genuine, distinct axes (category, symptom type, resolver mismatch, opened-hour bucket, unassigned-at-open) directly relevant to predicting longer resolution, and are largely grounded in the source text or original columns. The main weaknesses are is_recurring_issue_type, which is near-constant and appears unsupported per row, and the 'at_open' temporal columns whose grounding is only partially verifiable from current fields. Overall the set is useful and mostly well-grounded with one weak column."
}

